import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { mkdir, open, readFile, stat, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import { pathToFileURL } from 'node:url';
const base = '/workspace/issue-303';
const target = resolve(process.argv[2] ?? `${base}/baseline`);
const label = process.argv[3] ?? 'baseline';
const sdk = await import(pathToFileURL(`${process.env.BENCH_HOST ?? `${base}/worktree/node_modules/@earendil-works/pi-coding-agent`}/dist/index.js`));
const {readBrowserEntries} = await import(pathToFileURL(join(target,'dist/extensions/agent-browser/lib/browser-journal.js')));
const {SessionPageState} = await import(pathToFileURL(join(target,'dist/extensions/agent-browser/lib/session-page-state.js')));
const root = `${base}/evidence/synthetic`;
await mkdir(root,{recursive:true});
const file=join(root,'large-v2.jsonl');
const timestamp='2026-10-24T00:00:00.000Z';
const sessionId='11111111-1111-4111-8111-111111111303';
const count=5180;
try { await stat(file); } catch (e) {
 if (e.code !== 'ENOENT') throw e;
 const handle=await open(file,'wx',0o600);
 try {
  await handle.write(JSON.stringify({type:'session',version:3,id:sessionId,cwd:root,timestamp})+'\n');
  await handle.write(JSON.stringify({type:'thinking_level_change',id:'thinking',parentId:null,timestamp,thinkingLevel:'off'})+'\n');
  await handle.write(JSON.stringify({type:'message',id:'seed',parentId:'thinking',timestamp,message:{role:'assistant',content:[{type:'text',text:'Synthetic cloud benchmark.'}],api:'openai-completions',provider:'fixture',model:'fixture',stopReason:'stop',timestamp:1792800000000,usage:{input:0,output:0,cacheRead:0,cacheWrite:0,totalTokens:0,cost:{input:0,output:0,cacheRead:0,cacheWrite:0,total:0}}}})+'\n');
  for(let n=0;n<count;n++) await handle.write(JSON.stringify({type:'custom',customType:'synthetic-ignored',id:`entry-${n}`,parentId:n===0?'seed':`entry-${n-1}`,timestamp,data:{ignored:'x'.repeat(8192)}})+'\n');
  for(const id of ['branch-a','branch-b']) await handle.write(JSON.stringify({type:'custom',customType:'agent-browser-transition',id,parentId:`entry-${count-1}`,timestamp,data:{event:{version:1,phase:'state',operationId:id,toolCallId:id,commandIndex:0,isError:false,state:{},pages:[{key:'synthetic-shared',target:{url:`https://fixture.test/${id}`},refs:{kind:'invalidate'}}]}}})+'\n');
 } finally {await handle.close();}
}
const inputBytes=await readFile(file); const inputHash=createHash('sha256').update(inputBytes).digest('hex');
const sm=sdk.SessionManager.open(file,root);
const settingsManager=sdk.SettingsManager.inMemory({compaction:{enabled:false},retry:{enabled:false}});
const agentDir=join(root,'agent'); await mkdir(agentDir,{recursive:true});
const modelRuntime=await sdk.ModelRuntime.create({allowModelNetwork:false,authPath:join(agentDir,'auth.json'),modelsPath:null,modelsStorePath:join(agentDir,'models-store.json')});
const errors=[]; let starts=0,trees=0;
const loader=new sdk.DefaultResourceLoader({cwd:root,agentDir,settingsManager,noExtensions:true,noContextFiles:true,noSkills:true,noPromptTemplates:true,noThemes:true,additionalExtensionPaths:[join(target,'dist/extensions/agent-browser/index.js')],extensionFactories:[pi=>{pi.on('session_start',()=>{starts++});pi.on('session_tree',()=>{trees++});}]});
await loader.reload(); assert.deepEqual(loader.getExtensions().errors,[]);
const {session}=await sdk.createAgentSession({cwd:root,agentDir,modelRuntime,resourceLoader:loader,settingsManager,sessionManager:sm,noTools:'builtin'});
const timed=async(work)=>{const cpu=process.cpuUsage();const start=performance.now();const result=await work();return {ms:performance.now()-start,cpu:process.cpuUsage(cpu),result}};
const verify=async(id)=>{const entries=await readBrowserEntries(sm);assert.equal(entries.length,1); const page=SessionPageState.fromBranch(entries).get('synthetic-shared');assert.equal(page.tabTarget?.url,`https://fixture.test/${id}`);return{records:entries.length,url:page.tabTarget.url}};
try {
 const startup=await timed(()=>session.bindExtensions({onError:error=>errors.push(error)}));
 assert.equal(starts,1); assert.deepEqual(errors,[]);
 await verify('branch-b');
 for(const leaf of ['branch-a','branch-b']){await session.navigateTree(leaf);await verify(leaf);}
 const micro=await timed(()=>readBrowserEntries(sm));assert.equal(micro.result.length,1);delete micro.result;
 const tree=await timed(()=>session.navigateTree('branch-a'));assert.equal(tree.result.cancelled,false);delete tree.result;
 const output=await verify('branch-a'); assert.equal(createHash('sha256').update(await readFile(file)).digest('hex'),inputHash,'SDK must not change the matched fixture');
 assert.deepEqual(errors,[]);assert.equal(trees,3);
 console.log(JSON.stringify({label,node:process.version,sdk:JSON.parse(await readFile(`${process.env.BENCH_HOST ?? `${base}/worktree/node_modules/@earendil-works/pi-coding-agent`}/package.json`,'utf8')).version,fixture:{bytes:(await stat(file)).size,entries:count+4,sha256:createHash('sha256').update(await readFile(file)).digest('hex')},startup:{ms:startup.ms,cpu:startup.cpu},micro,tree,output,errors:errors.length,events:{starts,trees}}));
} finally {session.dispose();}

